static bool watch=false;static unsigned allocations=0;
void*operator new(std::size_t n){if(watch)++allocations;if(void*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
void operator delete(void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}
#define CHECK(x) do{if(!(x)){std::fprintf(stderr,"FAIL %d %s\n",__LINE__,#x);std::exit(1);}}while(false)
struct Synth{bs_synth*s=bs_create();Synth(){CHECK(s&&bs_prepare(s,48000));for(auto x:{std::pair<unsigned,float>{BS_GAIN,.15f},{BS_OSC1_LEVEL,.7f},{BS_OSC2_LEVEL,0},{BS_OSC1_WAVE,BS_SAW},{BS_FILTER_MIX,0},{BS_DRIFT_CENTS,0},{BS_SETTLING_CENTS,0},{BS_FULLNESS_ENABLED,0},{BS_ATTACK,.001f},{BS_DECAY,.04f},{BS_SUSTAIN_LEVEL,1},{BS_RELEASE,.04f}})CHECK(bs_set_parameter(s,x.first,x.second));bs_reset(s);}~Synth(){bs_destroy(s);}void on(){bs_note_on(s,0,60,.8f);}};
static std::vector<float>render(bs_synth*s,unsigned n=12000,unsigned block=127){std::vector<float>a(n*2);for(unsigned i=0;i<n;i+=block){watch=true;CHECK(bs_render(s,a.data()+i,a.data()+n+i,std::min(block,n-i),nullptr,0)==0);watch=false;}for(float x:a)CHECK(std::isfinite(x)&&std::abs(x)<=.981f);return a;}
static double energy(const std::vector<float>&a){double sum=0;for(float x:a)sum+=double(x)*x;return std::sqrt(sum/a.size());}
static double delta(const std::vector<float>&a,const std::vector<float>&b){CHECK(a.size()==b.size());double sum=0;for(unsigned i=0;i<a.size();++i)sum+=std::pow(double(a[i])-b[i],2);return std::sqrt(sum/a.size());}
static double frequency(const std::vector<float>&a){const unsigned n=a.size()/2;std::vector<double>cross;for(unsigned i=1;i<n;++i)if(a[i-1]<=0&&a[i]>0)cross.push_back(i-1-double(a[i-1])/(a[i]-a[i-1]));CHECK(cross.size()>8);return 48000*(cross.size()-1)/(cross.back()-cross.front());}
static bs_envelopes_config envelope(bs_synth*s,unsigned kind,unsigned id,unsigned p,float depth){bs_envelopes_config c{};CHECK(bs_get_envelopes(s,&c));auto&e=c.sources[2];e.attack=.001f;e.decay=.01f;e.sustain=1;e.release=.04f;e.route_count=1;e.routes[0]={kind,id,p,depth};return c;}
static bs_modulation_config_v4 constantLfo(unsigned kind,unsigned id,unsigned p,float depth){bs_modulation_config_v4 c{};bs_default_modulation_v4(&c);auto&e=c.sources[0];e.enabled=1;e.synced=0;e.waveform=BS_LFO_CUSTOM;e.point_count=2;e.points[0]={0,1,0};e.points[1]={1,1,0};e.route_count=1;e.routes[0]={kind,id,p,depth};return c;}
